window.BANK=window.BANK||{};window.BANK["8081"]={"n":"第四章 明确价值要求 践行价值准则","qs":[{"i":"163274","t":"单选","q":"人民当家作主的社会主义制度，为社会主义核心价值观的真正实现奠定了根本的制度前提和制度保障，使得自由、民主、公正等价值观“不是装饰品，不是用来做摆设的，而是要用来解决人民要解决的问题的”。这体现的是社会主义核心价值观具有的","o":{"A":"A.先进性","B":"B.人民性","C":"C.普适性","D":"D.真实性"},"a":"D","j":"<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>出处：肖老师精讲精练P300考点28</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>考点28因真实可信而具有强大的道义力量（真实性）</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>社会主义核心价值观与以往价值观的一个重要区别在于其真实性。</strong>中国特色社会主义的成验证了社会主义核心价值观的正确性，可信性。成功也验证了社会主义核心价值观的<strong>正确性、可信性</strong>，使得社会主义核心价值观可以而且能够成为真切、具体、广泛的现实为真切、具体、广泛的现实。</span></p>\n<p>&nbsp;</p>","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":14535,"tot":33417},{"i":"163275","t":"单选","q":"社会主义核心价值观的根本特性是","o":{"A":"A.先进性","B":"B.人民性","C":"C.普适性","D":"D.真实性"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P300考点27</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>考点27彰显人民至上的价值立场(人民性)重要</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>人民性是社会主义核心价值观的根本特性。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1尊重人民群众历史主体地位。</strong>人民至上是社会主义核心价值观鲜明的价值立场。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2. 体现以人民为中心的价值导向。</strong>鲜明的人民性使得社会主义核心价值观具有强大的感召力。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>人民性是社会主义核心价值观的根本特性。B正确，A、D不符合题意。C错误。</p>","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":24276,"tot":30934},{"i":"163276","t":"单选","q":"社会主义核心价值观的先进性集中体现在","o":{"A":"A.它是社会主义所坚持和追求的价值理念","B":"B.它吸纳了世界文明有益成果","C":"C.它是真切、具体、广泛的现实","D":"D.它扎根于中华优秀传统文化土壤"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P300考点26-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1体现社会主义的本质属性。</strong>社会主义核心价值观的先进性，集中体现在它是社会主义所坚持和追求的价值理念。社会主义核心价值观是我国社会主义制度的内在精神之魂，是中国特色社会主义本质规定的价值表达。</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":20650,"tot":31837},{"i":"163277","t":"多选","q":"社会主义核心价值观的基本内容是富强、民主、文明、和谐，自由、平等、公正、法治，爱国、敬业、诚信、友善。自由、平等、公正、法治回答了建设什么样的社会的重大问题，与实现国家治理体系和治理能力现代化的要求相契合，揭示了社会主义社会发展的价值取向。以下选项内容正确的有","o":{"A":"A.自由是社会活力之源，是社会主义的价值理想","B":"B.平等是人类追求的普世价值","C":"C.公正是人类社会进步的标尺，是社会主义制度的本质要求","D":"D.法治是人类政治文明的重要成果，是现代社会的主要特征"},"a":"ACD","j":"<p><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P299考点24表格</span></strong></p>\n<p><img src=\"data:image/png;base64,\" alt=\"\" /></p>\n<p><strong>简析：</strong>自由是社会活力之源，是社会主义的价值理想。平等是人类追求的美好状态。公正是人类社会进步的标尺，是社会主义制度的本质要求。法治是人类政治文明的重要成果，是现代社会的主要特征。A、C、D正确，B错误。点拨①西方国家所谓的&ldquo;普世价值&rdquo;,并非指人类道德评价、审美评价的普遍性或共性，而是特指资本主义价值观；推行的并不是人类共同的价值观，而是特定的价值观及其背后的经济政治文化制度。②反对西方所谓的&ldquo;普世价值&rdquo;,并不是说人类社会不存在共同价值。我们所主张的共同价值，是要倡导求同存异、和而不同，充分尊重文明的多样性，尊重各国自主选择社会制度和发展道路的权利。</p>","k":"考点20 社会主义核心价值观和社会主义核心价值体系","kid":"386","r":13975,"tot":31878},{"i":"163278","t":"多选","q":"社会主义核心价值观","o":{"A":"A.是当代中国精神的集中体现","B":"B.凝结着全体人民共同的价值追求","C":"C.集中体现社会主义的本质属性","D":"D.是整个上层建筑的核心"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P298考点23-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.社会主义核心价值观</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">社会主义核心价值观是当代中国精神的集中体现，是中国特色社会主义道路、理论、制度、文化价值表达，集中体现社会主义的价值追求。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">党的十八大提出，<strong>要倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。</strong>社会主义核心价值观的提出，鲜明确立了当代中国的核心价值理念，生动展现了中国共产党和中华民族高度的价值自觉与价值自信。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>社会主义核心价值观是当代中国精神的集中体现，是中国特色社会主义道路、理论、制度、文化的价值表达，集中体现社会主义的本质属性，凝结着全体人民共同的价值追求，体现了社会主义意识形态的本质要求。全社会积极弘扬和践行社会主义核心价值观，才能汇聚起建设社会主义现代化强国和实现中华民族伟大复兴的中国梦的磅礴力量。A、B、C正确。核心价值观在一个社会的思想观念体系中处于主导地位。在整个上层建筑中，国家政权是核心，D错误。</p>","k":"考点19 价值观、核心价值观与社会主义核心价值观","kid":"385","r":23154,"tot":29949}]};
